/* DAC 挂 APB1，先开时钟再复位 */
RCC_APB1PeriphClockCmd(RCC_APB1Periph_DAC, ENABLE);
DAC_DeInit();

/* C8T6 上没有 DAC 外设，以上代码在 C8T6 上不会产生任何实际输出 */

DAC_InitTypeDef DAC_InitStructure;
GPIO_InitTypeDef GPIO_InitStructure;

/* 1. 开时钟：DAC 在 APB1，GPIOA 在 APB2 */
RCC_APB1PeriphClockCmd(RCC_APB1Periph_DAC, ENABLE);
RCC_APB2PeriphClockCmd(RCC_APB2Periph_GPIOA, ENABLE);

/* 2. 输出引脚必须配成模拟输入，让数字部分彻底脱离引脚 */
GPIO_InitStructure.GPIO_Pin = GPIO_Pin_4;              /* DAC1 -> PA4 */
GPIO_InitStructure.GPIO_Mode = GPIO_Mode_AIN;
GPIO_Init(GPIOA, &GPIO_InitStructure);

/* 3. 先取默认值再改字段 */
DAC_StructInit(&DAC_InitStructure);
DAC_InitStructure.DAC_Trigger = DAC_Trigger_None;      /* 写入即转换，最简单 */
DAC_InitStructure.DAC_WaveGeneration = DAC_WaveGeneration_None;
DAC_InitStructure.DAC_LFSRUnmask_TriangleAmplitude = DAC_LFSRUnmask_Bit0;
DAC_InitStructure.DAC_OutputBuffer = DAC_OutputBuffer_Enable;
DAC_Init(DAC_Channel_1, &DAC_InitStructure);

/* 4. 使能通道并给一个初值 */
DAC_Cmd(DAC_Channel_1, ENABLE);
DAC_SetChannel1Data(DAC_Align_12b_R, 2048);            /* 约 1/2 VREF */

DAC_InitTypeDef DAC_InitStructure;

DAC_StructInit(&DAC_InitStructure);   /* 先清成默认值 */

/* 只改需要改的字段 */
DAC_InitStructure.DAC_Trigger = DAC_Trigger_None;
DAC_InitStructure.DAC_OutputBuffer = DAC_OutputBuffer_Enable;

DAC_Init(DAC_Channel_1, &DAC_InitStructure);

DAC_Init(DAC_Channel_1, &DAC_InitStructure);
DAC_Cmd(DAC_Channel_1, ENABLE);                        /* 不调这句通道不工作 */
DAC_SetChannel1Data(DAC_Align_12b_R, 2048);

NVIC_InitTypeDef NVIC_InitStructure;

DAC_ITConfig(DAC_Channel_1, DAC_IT_DMAUDR, ENABLE);

NVIC_InitStructure.NVIC_IRQChannel = DAC_IRQn;
NVIC_InitStructure.NVIC_IRQChannelPreemptionPriority = 2;
NVIC_InitStructure.NVIC_IRQChannelSubPriority = 0;
NVIC_InitStructure.NVIC_IRQChannelCmd = ENABLE;
NVIC_Init(&NVIC_InitStructure);

void DAC_IRQHandler(void)
{
  if (DAC_GetITStatus(DAC_Channel_1, DAC_IT_DMAUDR) != RESET)
  {
    /* DMA 跟不上 DAC：检查 DMA 是否停了、传输长度是否用完 */
    DMA_Cmd(DMA1_Channel3, ENABLE);
    DAC_ClearITPendingBit(DAC_Channel_1, DAC_IT_DMAUDR);
  }
}

/* 用 DMA 把正弦表循环送到 DAC1，实现自动波形输出 */
DAC_InitTypeDef DAC_InitStructure;
DMA_InitTypeDef DMA_InitStructure;

RCC_AHBPeriphClockCmd(RCC_AHBPeriph_DMA1, ENABLE);

DAC_InitStructure.DAC_Trigger = DAC_Trigger_T2_TRGO;   /* 定时器 2 触发 */
DAC_InitStructure.DAC_WaveGeneration = DAC_WaveGeneration_None;
DAC_InitStructure.DAC_OutputBuffer = DAC_OutputBuffer_Enable;
DAC_Init(DAC_Channel_1, &DAC_InitStructure);
DAC_Cmd(DAC_Channel_1, ENABLE);

/* DAC 通道 1 固定用 DMA1_Channel3 */
DMA_InitStructure.DMA_PeripheralBaseAddr = (uint32_t)&DAC->DHR12R1;
DMA_InitStructure.DMA_MemoryBaseAddr = (uint32_t)sine_table;
DMA_InitStructure.DMA_DIR = DMA_DIR_PeripheralDST;
DMA_InitStructure.DMA_BufferSize = SINE_TABLE_SIZE;
DMA_InitStructure.DMA_PeripheralInc = DMA_PeripheralInc_Disable;
DMA_InitStructure.DMA_MemoryInc = DMA_MemoryInc_Enable;
DMA_InitStructure.DMA_PeripheralDataSize = DMA_PeripheralDataSize_HalfWord;
DMA_InitStructure.DMA_MemoryDataSize = DMA_MemoryDataSize_HalfWord;
DMA_InitStructure.DMA_Mode = DMA_Mode_Circular;         /* 循环，波形持续输出 */
DMA_InitStructure.DMA_Priority = DMA_Priority_High;
DMA_InitStructure.DMA_M2M = DMA_M2M_Disable;
DMA_Init(DMA1_Channel3, &DMA_InitStructure);
DMA_Cmd(DMA1_Channel3, ENABLE);

DAC_DMACmd(DAC_Channel_1, ENABLE);                      /* 打通 DAC 到 DMA 的请求 */

/* DAC_Trigger 必须设为 DAC_Trigger_Software */
DAC_InitStructure.DAC_Trigger = DAC_Trigger_Software;
DAC_Init(DAC_Channel_1, &DAC_InitStructure);
DAC_Cmd(DAC_Channel_1, ENABLE);

/* 更新一次输出：先写数据，再软件触发 */
DAC_SetChannel1Data(DAC_Align_12b_R, 3000);
DAC_SoftwareTriggerCmd(DAC_Channel_1, ENABLE);

/* 想输出阶梯波，就在循环里重复上面两行 */

/* 两路通道都要配成软件触发 */
DAC_InitStructure.DAC_Trigger = DAC_Trigger_Software;
DAC_Init(DAC_Channel_1, &DAC_InitStructure);
DAC_Init(DAC_Channel_2, &DAC_InitStructure);
DAC_Cmd(DAC_Channel_1, ENABLE);
DAC_Cmd(DAC_Channel_2, ENABLE);

/* 同时写两路数据，再同时触发，保证两路完全同步 */
DAC_SetDualChannelData(DAC_Align_12b_R, 2048, 1024);   /* Data2=2048, Data1=1024 */
DAC_DualSoftwareTriggerCmd(ENABLE);

/* 定时器 2 以 100kHz 触发，DAC 输出三角波 */
DAC_InitStructure.DAC_Trigger = DAC_Trigger_T2_TRGO;      /* 必须有触发源 */
DAC_InitStructure.DAC_WaveGeneration = DAC_WaveGeneration_Triangle;
DAC_InitStructure.DAC_LFSRUnmask_TriangleAmplitude = DAC_TriangleAmplitude_2047;
DAC_Init(DAC_Channel_1, &DAC_InitStructure);

DAC_Cmd(DAC_Channel_1, ENABLE);

/* DHR 的值是三角波的起始基准电压 */
DAC_SetChannel1Data(DAC_Align_12b_R, 0);

/* 打开三角波生成（幅度已在 DAC_Init 里设定） */
DAC_WaveGenerationCmd(DAC_Channel_1, DAC_Wave_Triangle, ENABLE);

/* 用 12 位右对齐输出 1.65V（VREF+ = 3.3V） */
uint16_t value = (uint16_t)(1.65f / 3.3f * 4095.0f);   /* 约 2047 */
DAC_SetChannel1Data(DAC_Align_12b_R, value);

/* 输出 0V 到 3.3V 的三角扫描 */
for (uint16_t v = 0; v < 4096; v++)
{
  DAC_SetChannel1Data(DAC_Align_12b_R, v);
  /* 若 DAC_Trigger 是 Software，这里还要 DAC_SoftwareTriggerCmd(DAC_Channel_1, ENABLE); */
  delay_us(10);
}

/* 通道 2 输出 2.0V（VREF+ = 3.3V） */
uint16_t v2 = (uint16_t)(2.0f / 3.3f * 4095.0f);
DAC_SetChannel2Data(DAC_Align_12b_R, v2);

/* 参数顺序是 (对齐, 通道2数据, 通道1数据)，别写反 */
DAC_SetDualChannelData(DAC_Align_12b_R, 3000, 1000);
/* 结果：通道 2 = 3000，通道 1 = 1000 */

/* 两路同时更新输出 */
DAC_DualSoftwareTriggerCmd(ENABLE);

/* 增量调整：读回当前值后加一点 */
uint16_t now = DAC_GetDataOutputValue(DAC_Channel_1);

if (now < 4000)
{
  DAC_SetChannel1Data(DAC_Align_12b_R, now + 100);
  DAC_SoftwareTriggerCmd(DAC_Channel_1, ENABLE);
}

/* 主循环里轮询下溢标志 */
if (DAC_GetFlagStatus(DAC_Channel_1, DAC_FLAG_DMAUDR) != RESET)
{
  DAC_ClearFlag(DAC_Channel_1, DAC_FLAG_DMAUDR);
  /* 下溢说明 DMA 带宽不足：减小数据量、提高优先级或降低触发频率 */
}

void DAC_IRQHandler(void)
{
  if (DAC_GetITStatus(DAC_Channel_1, DAC_IT_DMAUDR) != RESET)
  {
    dma_underrun_count++;
    DAC_ClearITPendingBit(DAC_Channel_1, DAC_IT_DMAUDR);
  }
}

void DAC_IRQHandler(void)
{
  if (DAC_GetITStatus(DAC_Channel_1, DAC_IT_DMAUDR) != RESET)
  {
    /* 先修复 DMA，再清标志，否则立刻又下溢 */
    DMA_Cmd(DMA1_Channel3, ENABLE);
    DAC_ClearITPendingBit(DAC_Channel_1, DAC_IT_DMAUDR);
  }
}
